+      if (destroyed || editor) return;
+      editor = target;
+    }
+  };
+
+  return plugin;
+}
+
+export function attachAIAssistantPlugin(plugin: AIAssistantPlugin, editor: EditorAPI): void {
+  plugin.attachEditor(editor);
+}

